Object.assign(n[2482],{"tool":"sh","run":"printf 'sa@\\nso0\\n$!\\n$1\\n' > custom.rule && hashcat --force {{wordlist}} -r custom.rule --stdout | sort -u > mut.list","note":"Hand-rolled rules: sa@ (a→@), so0 (o→0), $! / $1 (append ! / 1). Stack two rules with -r r1 -r r2 for squared coverage."});
