Object.assign(n[4246],{"tool":"xfreerdp","run":"xfreerdp /v:{{target}} /u:{{user}} /p:'{{password}}' /d:{{domain}} /cert:ignore +clipboard /dynamic-resolution","note":"Get a real desktop first. OffSec doctrine: prefer RDP over WinRM for enumeration — WinRM hits the Kerberos double-hop problem (your session cannot re-authenticate to the DC for some queries). /cert:ignore quiets prompts.","opts":n[4247]});
n[4247].push(n[4248],n[4249],n[4250],n[4251]);
Object.assign(n[4248],{"flag":"/cert:ignore","semantic":"Ignore certificate warnings","tip":"Useful with self-signed lab RDP certificates.","category":"Network"});
Object.assign(n[4249],{"flag":"+clipboard","semantic":"Enable clipboard","tip":"Share clipboard with the RDP session.","category":"Session"});
Object.assign(n[4250],{"flag":"/dynamic-resolution","semantic":"Dynamic resolution","tip":"Resize the desktop with the client window.","category":"Session"});
Object.assign(n[4251],{"flag":"/sec:nla","semantic":"Require NLA","tip":"Force Network Level Authentication.","category":"Authentication","advanced":true});
Object.assign(n[4252],{"tool":"cmd","run":"net user /domain","note":"Every domain user. Then per-user detail: net user {{user}} /domain — group memberships, last logon, password age, account flags."});
Object.assign(n[4253],{"tool":"cmd","run":"net group /domain","note":"Every domain group. Membership: net group \"Domain Admins\" /domain — quote multiword names. net localgroup administrators on a specific host shows local admins."});
Object.assign(n[4254],{"tool":"cmd","run":"net accounts /domain","note":"Domain password and lockout policy — REQUIRED reading before any spraying (see password-spray). Lockout threshold minus one is your budget."});
Object.assign(n[4255],{"tool":"cmd","run":"setspn -L {{user}}","note":"SPNs registered to a service account (installed by default). HTTP/, MSSQLSvc/, termsrv/ SPNs reveal services AND kerberoast targets without a port scan. nslookup the SPN hostname to get its internal IP."});
Object.assign(n[4256],{"tool":"cmd","run":"nltest /dclist:{{domain}}","note":"Domain controllers. Also: nltest /domain_trusts for trust relationships (see trust-enum)."});
