Object.assign(n[4269],{"tool":"powershell","run":"powershell -ep bypass","note":"Bypass execution policy first so scripts/functions actually load. -ep bypass is per-process and not a system change.","operatorSurface40":"windows","operatorSurface41Source":"audited-v4.1"});
Object.assign(n[4270],{"tool":"powershell","run":"[System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()","note":"Domain object: forest, DCs, and PdcRoleOwner — the DC with the freshest data. $PDC = ...GetCurrentDomain().PdcRoleOwner.Name","operatorSurface40":"windows","operatorSurface41Source":"audited-v4.1"});
Object.assign(n[4271],{"tool":"powershell","run":"([adsi]'').distinguishedName","note":"One-liner for the domain DN (DC=corp,DC=com). No imports needed.","operatorSurface40":"windows","operatorSurface41Source":"audited-v4.1"});
Object.assign(n[4272],{"tool":"powershell","run":"function LDAPSearch { param([string]$LDAPQuery) $PDC = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain().PdcRoleOwner.Name; $DistinguishedName = ([adsi]\"''\").distinguishedName; $DirectoryEntry = New-Object System.DirectoryServices.DirectoryEntry(\"LDAP://$PDC/$DistinguishedName\"); $DirectorySearcher = New-Object System.DirectoryServices.DirectorySearcher($DirectoryEntry, $LDAPQuery); return $DirectorySearcher.FindAll() }","note":"The reusable function — paste this whole line, or save as function.ps1 and Import-Module it. Every query below is one LDAPSearch call.","operatorSurface40":"windows","operatorSurface41Source":"audited-v4.1"});
Object.assign(n[4273],{"tool":"powershell","run":"LDAPSearch -LDAPQuery \"(samAccountType=805306368)\"","note":"All user objects. 805306368 = user account type. Add .properties.samaccountname for clean names.","operatorSurface40":"windows","operatorSurface41Source":"audited-v4.1"});
Object.assign(n[4274],{"tool":"powershell","run":"LDAPSearch -LDAPQuery \"(objectclass=group)\"","note":"All groups. For membership: LDAPSearch -LDAPQuery \"(&(objectCategory=group)(cn=Sales Department))\" | ForEach-Object { $_.properties.member }","operatorSurface40":"windows","operatorSurface41Source":"audited-v4.1"});
Object.assign(n[4275],{"tool":"powershell","run":"LDAPSearch -LDAPQuery \"(&(objectCategory=person)(objectClass=user)(servicePrincipalName=*))\"","note":"SPN-bearing users = kerberoast targets, found without PowerView. Also try (adminCount=1) for protected/privileged accounts and (!(userAccountControl:1.2.840.113556.1.4.803:=2)) for enabled accounts only.","operatorSurface40":"windows","operatorSurface41Source":"audited-v4.1"});
n[4276].push("DC=","LDAP://","distinguishedname");
