Object.assign(n[4330],{"id":"ad-machine-account-quota-v25","maneuver":"ad-machine-account-quota","workflow":"ad-control","title":"MachineAccountQuota & RBCD Readiness","hypothesis":"Resource-based constrained delegation often depends on controlling a machine account. Before treating RBCD as available, check the domain MachineAccountQuota and whether the current principal already controls a computer object. This is a precondition check, not an assumption.","prereq":n[4331],"produces":n[4334],"commands":n[4335],"expected":n[4343],"onFailure":n[4344],"defender":"Reading MachineAccountQuota is normal LDAP activity; computer creation itself logs Event 4741.","report":n[4346],"tools":n[4347],"os":n[4348],"lane":"ad","orange43":n[4349],"orange44":n[4351],"contract45":n[4353],"report47":n[4354],"evidence45":n[4357]});
