Object.assign(n[7735],{"id":"applocker-bypass58","title":"AppLocker Policy Review and Bypass Verification","hypothesis":"AppLocker bypass is a local execution-control problem, not a privilege fact. First capture the effective policy, then validate an allowed trusted-binary path with a benign operator-supplied test artifact that prints a unique marker. Policy discovery alone is not a bypass, and successful bypass does not imply administrator or SYSTEM.","prereq":n[7736],"produces":n[7738],"commands":n[7739],"expected":n[7745],"onFailure":n[7746],"defender":"Monitor unusual use of trusted .NET utilities such as MSBuild or InstallUtil from user-writable paths and correlate with AppLocker audit/enforcement events.","report":n[7749],"tools":n[7750],"os":n[7751],"refs":n[7752],"orange44":n[7753],"lane":"windows-privesc","evidence45":n[7755],"report47":n[7757],"orange43":n[7760],"atomic81":n[7762],"sourceInventory81":n[7763]});
