Object.assign(n[7796],{"id":"uac-bypass59","title":"UAC Bypass Verification","hypothesis":"A UAC bypass should prove only that a local process crossed from a filtered administrator token to an elevated token. Obol captures the current token first, uses a reversible per-user handler for a reviewed lab command, verifies the resulting integrity level independently, and never converts process launch alone into administrator proof.","prereq":n[7797],"produces":n[7799],"commands":n[7800],"expected":n[7807],"onFailure":n[7808],"defender":"Monitor unusual fodhelper.exe launches paired with HKCU\\Software\\Classes\\ms-settings handler changes and short-lived per-user shell commands.","report":n[7811],"tools":n[7812],"os":n[7813],"refs":n[7814],"orange44":n[7815],"lane":"windows-privesc","evidence45":n[7817],"report47":n[7819],"orange43":n[7822],"atomic81":n[7824],"sourceInventory81":n[7825]});
